/bin/bash -lc "node --input-type=module <<'JS'
import {chromium} from '/tmp/cpu-chart-browser/node_modules/playwright/index.mjs';
const browser = await chromium.launch({headless: true, channel: 'chromium'});
const page = await browser.newPage({viewport: {width: 1360, height: 900}});
const errors = [];
page.on('pageerror', e => errors.push(e.message));
await page.goto('http://localhost:5173');
await page.locator('.chart-host canvas').waitFor();
await page.waitForTimeout(500);
const canvas = await page.locator('canvas').elementHandle();
console.log('initial', await page.locator('.chart-host').evaluate(el => ({width:el.clientWidth, height:el.clientHeight, canvases:el.querySelectorAll('canvas').length})), 'errors', errors);
await page.screenshot({path:'/tmp/cpu-chart-light.png', fullPage:true});
await page.getByRole('button', {name:'Тёмная тема'}).click();
await page.waitForTimeout(100);
await page.screenshot({path:'/tmp/cpu-chart-dark.png', fullPage:true});
console.log('dark',await page.locator('.chart-host').getAttribute('class'));
const plot = await page.locator('.u-over').boundingBox();
await page.mouse.move(plot.x+plot.width*0.4,plot.y+plot.height*0.5);
await page.waitForTimeout(100);
console.log('tooltip', await page.locator('[class*=\"tooltip\"]').allTextContents());
await page.mouse.down();
await page.mouse.move(plot.x+plot.width*0.6,plot.y+plot.height*0.5,{steps:10});
await page.mouse.up();
await page.waitForTimeout(2200);
console.log('zoom retained', await page.locator('.chart-toolbar').textContent());
console.log('same canvas',await canvas.evaluate(el => el === document.querySelector('.chart-host canvas')));
await page.getByRole('button', {name:'24 часа · сейчас'}).click();
await page.setViewportSize({width:390,height:844});
await page.waitForTimeout(200);
console.log('mobile',await page.evaluate(()=>({pageWidth:document.documentElement.scrollWidth,viewport:innerWidth,host:document.querySelector('.chart-host').clientWidth,canvas:document.querySelector('canvas').getBoundingClientRect().width})), 'errors',errors);
await page.screenshot({path:'/tmp/cpu-chart-mobile.png',fullPage:true});
await browser.close();
if(errors.length) process.exit(1);
JS"

